import { useState, useCallback, useEffect } from 'react'
import { SearchBar } from '../components/SearchBar.js'
import { SearchResultsTable } from '../components/SearchResultsTable.js'
import { ImportReviewModal } from '../components/ImportReviewModal.js'
import {
  searchByEan,
  searchByKeyword,
  syncSupplier,
  importProduct,
  getSuppliers,
  fetchDstDetail,
  fetchKruitboschDetail,
  fetchGransierDetail
} from '../services/api.js'
import type { SupplierOffer, ImportRequest, ImportResult, PaginationInfo, SupplierInfo, ProductDetail } from '../types.js'
import { computeFreshness, getFreshnessColorClass, getFreshnessTooltip } from '../utils/freshness.js'

type ActiveTab = 'dst' | 'kruitbosch' | 'gransier'

export function ProductFinderPage() {
  const [activeTab, setActiveTab] = useState<ActiveTab>('dst')
  const [offers, setOffers] = useState<SupplierOffer[]>([])
  const [pagination, setPagination] = useState<PaginationInfo | null>(null)
  const [lastQuery, setLastQuery] = useState<string>('')
  const [isLoading, setIsLoading] = useState(false)
  const [isImporting, setIsImporting] = useState(false)
  const [isSyncing, setIsSyncing] = useState(false)
  const [selectedOffer, setSelectedOffer] = useState<SupplierOffer | null>(null)
  const [importResult, setImportResult] = useState<ImportResult | null>(null)
  const [syncFeedback, setSyncFeedback] = useState<{ success: boolean; importedCount?: number; error?: string } | null>(null)
  const [suppliers, setSuppliers] = useState<SupplierInfo[]>([])

  // Load supplier list on mount
  useEffect(() => {
    getSuppliers()
      .then(data => setSuppliers(data.suppliers))
      .catch(() => {})
  }, [])

  // Enabled status helpers — used for disabling tabs and sync buttons
  const dstEnabled = suppliers.find(s => s.id === 'dst')?.enabled ?? false
  const kruitboschEnabled = suppliers.find(s => s.id === 'kruitbosch')?.enabled ?? false
  const gransierEnabled = suppliers.find(s => s.id === 'gransier')?.enabled ?? false

  // Freshness helpers — compute status for each supplier tab
  const getTabFreshness = useCallback((supplierId: string) => {
    const supplier = suppliers.find(s => s.id === supplierId)
    if (!supplier) return { colorClass: 'bg-red-500', tooltip: 'Unknown' }

    // DST uses auth status instead of sync timestamp
    if (supplierId === 'dst') {
      if (supplier.authStatus?.authenticated) {
        return { colorClass: 'bg-green-500', tooltip: 'DST authenticated and ready' }
      } else {
        return { colorClass: 'bg-red-500', tooltip: 'DST not authenticated — check credentials' }
      }
    }

    // For Gransier/Kruitbosch, use sync timestamp freshness
    const status = supplier.status ?? computeFreshness(supplier.lastSyncedAt)
    return {
      colorClass: getFreshnessColorClass(status),
      tooltip: getFreshnessTooltip(status, supplier.lastSyncedAt)
    }
  }, [suppliers])

  // Disable active tab if supplier is not enabled
  useEffect(() => {
    // Don't redirect until we've loaded the supplier list
    if (suppliers.length === 0) return
    if (activeTab === 'dst' && !dstEnabled) setActiveTab('kruitbosch')
    else if (activeTab === 'kruitbosch' && !kruitboschEnabled) setActiveTab('gransier')
    else if (activeTab === 'gransier' && !gransierEnabled) setActiveTab('dst')
  }, [suppliers.length, dstEnabled, kruitboschEnabled, gransierEnabled])

  const handleSearch = useCallback(async (query: string, mode: 'ean' | 'keyword', page = 0) => {
    setIsLoading(true)
    try {
      let results
      if (mode === 'ean') {
        results = await searchByEan(query, activeTab)
        setPagination(null) // EAN searches are unpaginated
      } else {
        results = await searchByKeyword(query, activeTab, page)
        setPagination(results.pagination ?? null)
        if (mode === 'keyword') {
          setLastQuery(query)
        }
      }
      setOffers(results.offers)
      setImportResult(null)
    } catch (err) {
      console.error('[Product Finder] Search failed:', err instanceof Error ? err.message : String(err))
      setOffers([])
      setPagination(null)
    } finally {
      setIsLoading(false)
    }
  }, [activeTab])

  const handleSync = useCallback(async (supplierId: string) => {
    setSyncFeedback(null)
    setIsSyncing(true)
    try {
      const result = await syncSupplier(supplierId)
      if (result.success) {
        setSyncFeedback({ success: true, importedCount: result.importedCount })
        console.log(`[Product Finder] Synced ${result.importedCount} products from ${supplierId}`)
      } else {
        setSyncFeedback({ success: false, error: 'Sync failed — check logs for details' })
        console.error('[Product Finder] Sync failed')
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      setSyncFeedback({ success: false, error: `Sync error: ${message}` })
      console.error('[Product Finder] Sync error:', message)
    } finally {
      setIsSyncing(false)
    }
  }, [])

  const handleImport = useCallback((offer: SupplierOffer) => {
    setSelectedOffer(offer)
  }, [])

  const handleConfirmImport = useCallback(async (request: ImportRequest) => {
    if (!selectedOffer) return
    setIsImporting(true)
    try {
      const result = await importProduct(request)
      setImportResult(result)
    } catch (err) {
      console.error('[Product Finder] Import failed:', err instanceof Error ? err.message : String(err))
      setImportResult({ success: false, action: 'updated', message: `Import failed: ${err instanceof Error ? err.message : 'Unknown error'}` })
    } finally {
      setIsImporting(false)
      setSelectedOffer(null)
    }
  }, [selectedOffer])

  const handleCloseModal = useCallback(() => {
    setSelectedOffer(null)
  }, [])

  const handlePageChange = useCallback((page: number) => {
    if (lastQuery) {
      void handleSearch(lastQuery, 'keyword', page)
    }
  }, [lastQuery, handleSearch])

  // ── Real detail fetcher — calls per-supplier API endpoints ───────────────
  const fetchProductDetail = useCallback(async (ean: string): Promise<ProductDetail> => {
    switch (activeTab) {
      case 'dst':
        return await fetchDstDetail(ean)

      case 'kruitbosch':
        return await fetchKruitboschDetail(ean)

      case 'gransier':
        return await fetchGransierDetail(ean)
    }
  }, [activeTab])

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Header */}
      <div className="px-6 py-4 border-b bg-card">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold">Product Finder</h1>
            <p className="text-sm text-muted-foreground mt-0.5">Search supplier catalogs and import products into your parts inventory</p>
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b bg-card px-6">
        <div className="flex gap-4">
          <button
            onClick={() => setActiveTab('dst')}
            className={`px-3 py-2 text-sm font-medium border-b-2 transition-colors flex items-center gap-1.5 ${
              activeTab === 'dst'
                ? 'border-primary text-foreground'
                : 'border-transparent text-muted-foreground hover:text-foreground'
            }`}
            disabled={!dstEnabled}
            title={getTabFreshness('dst').tooltip}
          >
            <span className={`inline-block w-2 h-2 rounded-full ${getTabFreshness('dst').colorClass}`} />
            DST Suppliers {dstEnabled ? '' : '(disabled)'}
          </button>
          <button
            onClick={() => setActiveTab('kruitbosch')}
            className={`px-3 py-2 text-sm font-medium border-b-2 transition-colors flex items-center gap-1.5 ${
              activeTab === 'kruitbosch'
                ? 'border-primary text-foreground'
                : 'border-transparent text-muted-foreground hover:text-foreground'
            }`}
            disabled={!kruitboschEnabled}
            title={getTabFreshness('kruitbosch').tooltip}
          >
            <span className={`inline-block w-2 h-2 rounded-full ${getTabFreshness('kruitbosch').colorClass}`} />
            Kruitbosch {kruitboschEnabled ? '' : '(disabled)'}
          </button>
          <button
            onClick={() => setActiveTab('gransier')}
            className={`px-3 py-2 text-sm font-medium border-b-2 transition-colors flex items-center gap-1.5 ${
              activeTab === 'gransier'
                ? 'border-primary text-foreground'
                : 'border-transparent text-muted-foreground hover:text-foreground'
            }`}
            disabled={!gransierEnabled}
            title={getTabFreshness('gransier').tooltip}
          >
            <span className={`inline-block w-2 h-2 rounded-full ${getTabFreshness('gransier').colorClass}`} />
            Gransier {gransierEnabled ? '' : '(disabled)'}
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-6 space-y-4">
        {/* Tab-specific header info */}
        {activeTab === 'dst' && (
          <div className="text-sm text-muted-foreground">
            Real-time search via DST API. Searches multiple suppliers through the DST aggregator.
          </div>
        )}

        {activeTab === 'kruitbosch' && (
          <div className="flex items-center justify-between">
            <div className="text-sm text-muted-foreground">
              Local catalog search from Kruitbosch.{' '}
              {!offers.length && 'Sync the catalog first to populate local data.'}
            </div>
            <button
              onClick={() => handleSync('kruitbosch')}
              disabled={isSyncing || !kruitboschEnabled}
              className="px-3 py-1.5 text-xs font-medium bg-primary text-primary-foreground rounded-md hover:opacity-90 disabled:opacity-50"
            >
              {isSyncing ? 'Syncing...' : 'Sync Catalog'}
            </button>
          </div>
        )}

        {activeTab === 'gransier' && (
          <div className="flex items-center justify-between">
            <div className="text-sm text-muted-foreground">
              Local catalog search from Gransier. Sync the catalog first to populate local data.
            </div>
            <button
              onClick={() => handleSync('gransier')}
              disabled={isSyncing || !gransierEnabled}
              className="px-3 py-1.5 text-xs font-medium bg-primary text-primary-foreground rounded-md hover:opacity-90 disabled:opacity-50"
            >
              {isSyncing ? 'Syncing...' : 'Sync Catalog'}
            </button>
          </div>
        )}

        {/* Search bar — DST disables keyword mode; others support both.
            key forces remount on tab switch so mode resets to the tab's default. */}
        <SearchBar
          key={activeTab}
          onSearch={handleSearch}
          isLoading={isLoading}
          defaultMode={activeTab === 'dst' ? 'ean' : 'keyword'}
          disabledModes={activeTab === 'dst' ? ['keyword'] : []}
        />

        {/* Results table */}
        <div className="border rounded-lg bg-card">
          <SearchResultsTable
            offers={offers}
            onImport={handleImport}
            isLoading={isLoading}
            pagination={pagination}
            onPageChange={handlePageChange}
            fetchDetail={fetchProductDetail}
          />
        </div>

        {/* Sync feedback */}
        {syncFeedback && (
          <div className={`p-3 rounded-md text-sm ${
            syncFeedback.success
              ? 'bg-green-50 border border-green-200 text-green-800'
              : 'bg-red-50 border border-red-200 text-red-800'
          }`}>
            {syncFeedback.success ? (
              <p className="font-medium">Sync complete — imported {syncFeedback.importedCount} products</p>
            ) : (
              <p className="font-medium">{syncFeedback.error}</p>
            )}
          </div>
        )}

        {/* Import result feedback */}
        {importResult && (
          <div className={`p-3 rounded-md text-sm ${
            importResult.success
              ? 'bg-green-50 border border-green-200 text-green-800'
              : 'bg-red-50 border border-red-200 text-red-800'
          }`}>
            <p className="font-medium">
              {importResult.success
                ? `${importResult.action === 'created' ? 'Created' : 'Updated'} part ${importResult.partId || ''}`
                : importResult.message}
            </p>
          </div>
        )}
      </div>

      {/* Import review modal */}
      {selectedOffer && (
        <ImportReviewModal
          offer={selectedOffer}
          onClose={handleCloseModal}
          onConfirm={handleConfirmImport}
          isImporting={isImporting}
        />
      )}
    </div>
  )
}

/**
 * Supplier Registry — Central list of all active supplier adapters.
 */

import type { SupplierAdapter, SupplierAuthStatus } from './base.js'
import { dstAdapter } from './dst/adapter.js'
import { kruitboschAdapter } from './kruitbosch/adapter.js'
import { gransierAdapter } from './gransier/adapter.js'
import { readSyncStatus, type SyncStatusFile } from '../../services/sync-status-service.js'

// ============================================================================
// All registered suppliers
// ============================================================================

const allSuppliers: SupplierAdapter[] = [
  dstAdapter,
  kruitboschAdapter,
  gransierAdapter
]

/** Get only enabled suppliers (based on env credentials) */
export function getActiveSuppliers(): SupplierAdapter[] {
  return allSuppliers.filter(s => s.isEnabled())
}

/** Find a supplier by ID */
export function findSupplier(id: string): SupplierAdapter | undefined {
  return allSuppliers.find(s => s.id === id)
}

/** Get all suppliers with their enabled status, sync status, and auth info (for UI) */
export async function getSupplierList(): Promise<Array<{
  id: string
  name: string
  enabled: boolean
  lastSyncedAt?: string | null
  status?: 'ok' | 'stale' | 'failed'
  authStatus?: SupplierAuthStatus
}>> {
  const result = await Promise.all(
    allSuppliers.map(async (s) => {
      const syncStatus = await readSyncStatus(s.id)
      const freshness = computeFreshness(syncStatus)

      return {
        id: s.id,
        name: s.name,
        enabled: s.isEnabled(),
        lastSyncedAt: syncStatus?.lastSyncedAt ?? undefined,
        status: freshness,
        authStatus: s.getStatus()
      }
    })
  )

  return result
}

/** Compute freshness category from sync status */
function computeFreshness(syncStatus: SyncStatusFile | null): 'ok' | 'stale' | 'failed' {
  // Never synced or failed sync → stale (will show red)
  if (!syncStatus || !syncStatus.lastSyncedAt) {
    return syncStatus?.error ? 'failed' : 'stale'
  }

  const lastSync = new Date(syncStatus.lastSyncedAt)
  const now = new Date()
  const hoursSinceSync = (now.getTime() - lastSync.getTime()) / (1000 * 60 * 60)

  if (hoursSinceSync < 24) {
    return 'ok' // same day → green
  } else if (hoursSinceSync < 120) { // 5 days = 120 hours
    return 'stale' // >1 day but ≤5 days → yellow
  } else {
    return 'failed' // >5 days → red
  }
}

