/**
 * Supplier Adapter — Contract every supplier must implement.
 *
 * Each supplier adapter handles its own auth, search strategy (real-time API or local cache),
 * and maps raw responses into the unified SupplierOffer shape.
 */

import type { SearchResults } from '../../types.js'

// ============================================================================
// Auth Status
// ============================================================================

export interface SupplierAuthStatus {
  /** Whether this supplier is authenticated and ready to search */
  authenticated: boolean
  /** Absolute expiry timestamp in ms, or null if no token/session */
  expiresAt: number | null
}

// ============================================================================
// Adapter Interface
// ============================================================================

/** Every supplier adapter must implement this interface */
export interface SupplierAdapter {
  /** Unique identifier (e.g. 'dst', 'kruitbosch') */
  id: string

  /** Display name shown in the UI */
  name: string

  /** Whether this supplier is enabled via environment variables */
  isEnabled(): boolean

  /** Current auth status — does not trigger auto-auth */
  getStatus(): SupplierAuthStatus

  /** Search by EAN barcode (exact match) */
  searchByEan(ean: string): Promise<SearchResults>

  /** Search by keyword with pagination */
  searchByKeyword(query: string, page?: number, pageSize?: number): Promise<SearchResults>

  /** Optional: sync fresh data from the supplier (for catalog-download suppliers) */
  sync?(): Promise<{ success: boolean; importedCount: number }>
}

import { describe, it, expect, beforeEach } from 'vitest'
import { TokenCache, type DstToken } from '../token-cache.js'

describe('DST Auth — Token Cache', () => {
  let cache: TokenCache

  beforeEach(() => {
    cache = new TokenCache()
  })

  // ---------------------------------------------------------------------------
  // Tracer bullet: basic store and retrieve
  // ---------------------------------------------------------------------------
  describe('store and retrieve', () => {
    it('should store a token and return it on subsequent calls', () => {
      const token: DstToken = {
        access_token: 'test-token-123',
        expires_in: 3600,
        scope: 'openid'
      }

      cache.store(token)

      const retrieved = cache.get()
      expect(retrieved).toBeDefined()
      expect(retrieved?.access_token).toBe('test-token-123')
      expect(retrieved?.scope).toBe('openid')
    })

    it('should return null when no token has been stored', () => {
      const retrieved = cache.get()
      expect(retrieved).toBeNull()
    })
  })

  // ---------------------------------------------------------------------------
  // Expiry detection
  // ---------------------------------------------------------------------------
  describe('expiry detection', () => {
    it('should report isExpired as false for a fresh token', () => {
      const token: DstToken = {
        access_token: 'fresh-token',
        expires_in: 3600,
        scope: 'openid'
      }

      cache.store(token)
      expect(cache.isExpired()).toBe(false)
    })

    it('should report isExpired as true when token has expired', () => {
      // Store a token that already expired (expires_in = 0 means expired now)
      const token: DstToken = {
        access_token: 'expired-token',
        expires_in: 0,
        scope: 'openid'
      }

      cache.store(token)
      expect(cache.isExpired()).toBe(true)
    })

    it('should report isExpired as true when token expired in the past', () => {
      // Simulate a token that expired 1 second ago by using negative expires_in
      const token: DstToken = {
        access_token: 'old-token',
        expires_in: -1,
        scope: 'openid'
      }

      cache.store(token)
      expect(cache.isExpired()).toBe(true)
    })
  })

  // ---------------------------------------------------------------------------
  // Auto-refresh: transparent token replacement
  // ---------------------------------------------------------------------------
  describe('auto-refresh', () => {
    it('should call refreshFn when token is near expiry and return the new token', async () => {
      // Store a token that expires in 3 minutes (within the 5-minute threshold)
      const oldToken: DstToken = {
        access_token: 'old-expiring-token',
        expires_in: 180, // 3 minutes
        scope: 'openid'
      }

      cache.store(oldToken)

      let refreshCalled = false
      const newToken: DstToken = {
        access_token: 'refreshed-token-456',
        expires_in: 3600,
        scope: 'openid'
      }

      // getWithRefresh should call the refresh function and return the new token
      const result = await cache.getWithRefresh(async () => {
        refreshCalled = true
        return newToken
      })

      expect(refreshCalled).toBe(true)
      expect(result?.access_token).toBe('refreshed-token-456')
    })

    it('should NOT call refreshFn when token is still valid (more than 5 min left)', async () => {
      const freshToken: DstToken = {
        access_token: 'fresh-token',
        expires_in: 3600, // 1 hour
        scope: 'openid'
      }

      cache.store(freshToken)

      let refreshCalled = false
      const newToken: DstToken = {
        access_token: 'should-not-appear',
        expires_in: 3600,
        scope: 'openid'
      }

      const result = await cache.getWithRefresh(async () => {
        refreshCalled = true
        return newToken
      })

      expect(refreshCalled).toBe(false)
      // Should still have the old token, not the new one
      expect(result?.access_token).toBe('fresh-token')
    })

    it('should call refreshFn when no token is cached at all', async () => {
      let refreshCalled = false
      const newToken: DstToken = {
        access_token: 'first-token',
        expires_in: 3600,
        scope: 'openid'
      }

      const result = await cache.getWithRefresh(async () => {
        refreshCalled = true
        return newToken
      })

      expect(refreshCalled).toBe(true)
      expect(result?.access_token).toBe('first-token')
    })
  })
})

