        username: 'wronguser',
        password: 'wrongpass',
        fetchFn: mockFetch as unknown as typeof fetch
      })

      expect(result.authenticated).toBe(false)
    })

    it('should return authenticated=false when Keycloak returns 500', async () => {
      const mockFetch = vi.fn().mockResolvedValue({
        ok: false,
        status: 500,
        json: async () => ({ error_description: 'Internal server error' })
      })

      const result = await authenticateWithDST({
        username: 'testuser',
        password: 'testpass',
        fetchFn: mockFetch as unknown as typeof fetch
      })

      expect(result.authenticated).toBe(false)
    })

