    it('should return authenticated=false when no token is cached', async () => {
      const status = getTokenStatus()

      expect(status.authenticated).toBe(false)
      expect(status.expiresAt).toBeNull()
    })

    it('should return the correct expiresAt timestamp after login', async () => {
      const mockFetch = vi.fn().mockResolvedValue({
        ok: true,
        json: async () => ({
          access_token: 'status-test-token',
          expires_in: 1800, // 30 minutes
          scope: 'openid'
        })
      })

      await authenticateWithDST({
        username: 'testuser',
        password: 'testpass',
        fetchFn: mockFetch as unknown as typeof fetch
      })

      const { getTokenStatus } = await import('../auth-service.js')
      const status = getTokenStatus()

      expect(status.authenticated).toBe(true)
      expect(typeof status.expiresAt).toBe('number')
      // expiresAt should be roughly now + 30 minutes in ms
      const expectedMin = Date.now() + 1795 * 1000
      const expectedMax = Date.now() + 1805 * 1000
      expect(status.expiresAt).toBeGreaterThanOrEqual(expectedMin)
      expect(status.expiresAt).toBeLessThanOrEqual(expectedMax)
