import type { SearchResults } from '../types.js'
import { findSupplier, getActiveSuppliers } from './suppliers/index.js'
import { deduplicateOffers, mapToSupplierOffer } from './suppliers/dst/adapter.js'

// ============================================================================
// Per-supplier search (used by routes)
// ============================================================================

/**
 * Search a specific supplier by EAN.
 */
export async function searchSupplierByEan(supplierId: string, ean: string): Promise<SearchResults> {
  const supplier = findSupplier(supplierId)
  if (!supplier) {
    throw new Error(`Unknown supplier: ${supplierId}`)
  }

  if (!supplier.isEnabled()) {
    return { offers: [] }
  }

  return await supplier.searchByEan(ean)
}

/**
 * Search a specific supplier by keyword.
 */
export async function searchSupplierByKeyword(
  supplierId: string,
  query: string,
  page = 0,
  pageSize = 20
): Promise<SearchResults> {
  const supplier = findSupplier(supplierId)
  if (!supplier) {
    throw new Error(`Unknown supplier: ${supplierId}`)
  }

  if (!supplier.isEnabled()) {
    return { offers: [], pagination: { page, pageSize, totalPages: 0, totalElements: 0 } }
  }

  return await supplier.searchByKeyword(query, page, pageSize)
}

// ============================================================================
// Combined search (all suppliers)
// ============================================================================

/**
 * Search all active suppliers by EAN and merge results.
 */
export async function searchAllByEan(ean: string): Promise<SearchResults> {
  const suppliers = getActiveSuppliers()
  if (suppliers.length === 0) {
    return { offers: [] }
  }

  // Search all suppliers in parallel
  const results = await Promise.allSettled(
    suppliers.map(s => s.searchByEan(ean))
  )

  const allOffers = results
    .filter((r): r is PromiseFulfilledResult<SearchResults> => r.status === 'fulfilled')
    .flatMap(r => r.value.offers)

  return { offers: allOffers }
}

/**
 * Search all active suppliers by keyword and merge results.
 */
export async function searchAllByKeyword(
  query: string,
  page = 0,
  pageSize = 20
): Promise<SearchResults> {
  const suppliers = getActiveSuppliers()
  if (suppliers.length === 0) {
    return { offers: [], pagination: { page, pageSize, totalPages: 0, totalElements: 0 } }
  }

  // Search all suppliers in parallel
  const results = await Promise.allSettled(
    suppliers.map(s => s.searchByKeyword(query, page, pageSize))
  )

  const allOffers = results
    .filter((r): r is PromiseFulfilledResult<SearchResults> => r.status === 'fulfilled')
    .flatMap(r => r.value.offers)

  return { offers: allOffers }
}

// ============================================================================
// Sync (for catalog-download suppliers like Kruitbosch)
// ============================================================================

/**
 * Trigger a sync for a specific supplier.
 */
export async function syncSupplier(supplierId: string): Promise<{ success: boolean; importedCount: number }> {
  const supplier = findSupplier(supplierId)
  if (!supplier) {
    throw new Error(`Unknown supplier: ${supplierId}`)
  }

  if (!supplier.sync) {
    throw new Error(`Supplier ${supplierId} does not support sync`)
  }

  return await supplier.sync()
}

