export async function getDstAuthStatus(): Promise<{
  authenticated: boolean
  expiresAt: number | null
}> {
  const response = await fetch(`${BASE_URL}/api/dst-auth/auth/status`)

  if (!response.ok) {
    throw new Error(`Failed to load auth status: ${response.status}`)
  }

  return response.json() as Promise<{ authenticated: boolean; expiresAt: number | null }>

